import {stories, sources} from './story-content.mjs';

export function sourceDisplay(source, language) {
  const originalLanguage = source.originalLanguage || 'en';
  return {originalLanguage, original: source[originalLanguage],
    translation: language === originalLanguage ? '' : source[language]};
}

export function createJourney() { return {owner: 'J', step: 0, language: 'ko', corrections: {}}; }
export function move(state, amount) {
  return {...state, step: Math.min(2, Math.max(0, state.step + amount))};
}
export function choose(state, owner) {
  if (!Object.hasOwn(stories, owner)) throw new Error('Unknown fictional person.');
  return owner === state.owner ? state : {...state, owner, step: 0};
}
export function revise(state, text) {
  return {...state, corrections: {...state.corrections, [`${state.owner}:${state.step}`]: text.trim().slice(0, 500)}};
}
export function current(state) {
  const story = stories[state.owner];
  const page = story.pages[state.step];
  return {story, page, copy: page[state.language],
    sources: page.refs.map(id => sources[id]),
    readPages: story.pages.slice(0, state.step + 1).map((p, index) => ({copy: p[state.language], sources: p.refs.map(id => sources[id]), correction: state.corrections[`${state.owner}:${index}`] || ''})),
    correction: state.corrections[`${state.owner}:${state.step}`] || ''};
}

