import {mascot} from './illustrations.mjs';
import {escape} from './ai.mjs';
import {stories, words, sourceContext} from './story-content.mjs';
import {createJourney, move, choose, revise, current, sourceDisplay} from './story-model.mjs';

let state = createJourney();
let editing = false;
const drafts = {};
const key = () => `${state.owner}:${state.step}`;
const app = document.querySelector('#app');
const status = document.querySelector('#status');

function sourceHtml(source, w) {
  const display = sourceDisplay(source, state.language);
  const label = source.kind === 'quote' ? (display.originalLanguage === 'ko' ? w.quoteKo : w.quote) : w.summary;
  return '<div class="source"><span>' + source.id + ' / ' + label
    + '</span><p lang="' + display.originalLanguage + '">' + escape(display.original) + '</p><small>' + w.context + '</small><p>'
    + escape(sourceContext[source.id][state.language]) + '</p>'
    + (display.translation ? '<small>' + (display.originalLanguage === 'ko' ? w.translation : w.paraphrase) + '</small><p>' + escape(display.translation) + '</p>' : '') + '</div>';
}

function render(focus) {
  const w = words[state.language];
  const {story, copy, sources, readPages, correction} = current(state);
  document.documentElement.lang = state.language;
  document.title = state.language === 'ko' ? 'Avatar — 대화 한 장 더 읽기' : 'Avatar — One more conversation';
  app.innerHTML = '<header><a class="brand" href="/">avatar<span class="brand-dot" aria-hidden="true">a</span></a>'
    + '<div class="header-actions"><a href="/">' + w.back + '</a><button class="language" data-action="language" lang="' + (state.language === 'ko' ? 'en' : 'ko') + '">' + w.language + '</button></div></header>'
    + '<main><section class="intro"><p class="demo-label">' + w.demo + '</p><h1>' + w.title + '<br>' + w.subtitle + '</h1><p>' + w.intro + '</p></section>'
    + '<div class="reading-room"><aside><fieldset><legend>' + w.people + '</legend><div class="people">'
    + Object.keys(stories).map(owner => '<button data-owner="' + owner + '" aria-pressed="' + (owner === state.owner) + '"><span>' + owner + '</span>' + stories[owner][state.language] + '</button>').join('')
    + '</div></fieldset><div class="friend">' + mascot(story.kind, state.language === 'ko' ? '대화를 읽는 작은 아바타' : 'A little avatar reading a conversation')
    + '</div><p class="aside-note">' + w.shift + '</p></aside>'
    + '<article class="letter" id="letter" tabindex="-1" aria-labelledby="story-title"><div class="letter-top"><span>' + state.owner + '</span><div class="dots" role="img" aria-label="' + w.reading + ' ' + (state.step + 1) + ' / 3">'
    + [0, 1, 2].map(i => '<i class="' + (i <= state.step ? 'read' : '') + '"></i>').join('') + '</div></div>'
    + '<p class="scene">' + copy.scene + '</p><h2 id="story-title">' + copy.title + '</h2>'
    + '<section class="observation"><h3>' + w.observation + '</h3><p>' + copy.observation + '</p></section>'
    + '<section class="interpretation"><h3>' + (correction ? w.corrected : w.interpretation) + '</h3><p class="meaning">' + escape(correction || copy.interpretation) + '</p>'
    + (correction ? '<details><summary>' + w.original + '</summary><p>' + copy.interpretation + '</p></details><button class="text-button" data-action="reset">' + w.reset + '</button>' : '') + '</section>'
    + '<p class="alternative"><b>' + w.alternative + '</b>' + copy.alternative + '</p>'
    + (state.step === 2 ? '<details class="learning"><summary>' + w.compare + '</summary><p class="quiet">' + w.comparisonNote + '</p>'
      + readPages.map(page => '<section><h3>' + escape(page.copy.scene) + '</h3><small>' + (page.correction ? w.corrected : w.before) + '</small><p>' + escape(page.correction || page.copy.interpretation) + '</p>'
        + (page.correction ? '<details><summary>' + w.original + '</summary><p>' + escape(page.copy.interpretation) + '</p></details>' : '')
        + '<details><summary>' + w.evidence + '</summary>' + page.sources.map(source => sourceHtml(source, w)).join('') + '</details></section>').join('') + '</details>' : '')
    + '<details class="evidence"><summary>' + w.evidence + '</summary>'
    + sources.map(source => sourceHtml(source, w)).join('') + '</details>'
    + (editing ? '<form id="edit-form"><label for="reflection">' + w.editLabel + '</label><textarea id="reflection" maxlength="500" required rows="3">' + escape(drafts[key()] ?? correction) + '</textarea><p>' + w.note + '</p><div class="edit-buttons"><button class="primary" type="submit">' + w.save + '</button><button type="button" class="text-button" data-action="cancel">' + w.cancel + '</button></div></form>'
      : '<button class="edit-link" data-action="edit">' + w.correction + '</button>')
    + '<div class="page-controls"><button data-action="previous"' + (state.step === 0 ? ' disabled' : '') + '>' + w.previous + '</button><button class="primary" data-action="next">' + (state.step === 2 ? w.again : w.next) + '<span aria-hidden="true">↗</span></button></div>'
    + '<p class="order-note">' + w.order + '</p></article></div>'
    + '<p class="method">' + w.method + '</p></main><footer><span>avatar</span><p>' + w.footer + '</p></footer>';
  if (focus) document.querySelector(focus)?.focus({preventScroll: true});
  if (focus === '#letter') document.querySelector('#letter').scrollIntoView({block: 'start', behavior: 'instant'});
}

app.addEventListener('click', event => {
  const button = event.target.closest('button');
  if (!button) return;
  if (button.dataset.owner) {
    if (button.dataset.owner === state.owner) return;
    state = choose(state, button.dataset.owner); editing = Object.hasOwn(drafts, key());
    render('[data-owner="' + state.owner + '"]'); return;
  }
  const action = button.dataset.action;
  if (!action) return;
  if (action === 'language') { state = {...state, language: state.language === 'ko' ? 'en' : 'ko'}; render('[data-action="language"]'); return; }
  if (action === 'edit') { editing = true; render('#reflection'); return; }
  if (action === 'cancel') { delete drafts[key()]; editing = false; render('[data-action="edit"]'); return; }
  if (action === 'reset') { state = revise(state, ''); delete drafts[key()]; editing = false; render('[data-action="edit"]'); status.textContent = words[state.language].removed; return; }
  state = action === 'previous' ? move(state, -1) : {...state, step: state.step === 2 ? 0 : state.step + 1};
  editing = Object.hasOwn(drafts, key()); render('#letter');
});

app.addEventListener('submit', event => {
  if (event.target.id !== 'edit-form') return;
  event.preventDefault();
  const input = document.querySelector('#reflection');
  if (!input.value.trim()) { input.setCustomValidity(words[state.language].error); input.reportValidity(); return; }
  state = revise(state, input.value); delete drafts[key()]; editing = false; render('[data-action="edit"]');
  status.textContent = words[state.language].changed;
});
app.addEventListener('input', event => { if (event.target.id === 'reflection') { event.target.setCustomValidity(''); drafts[key()] = event.target.value; } });
render();

