import test from 'node:test';
import assert from 'node:assert/strict';
import {createJourney, move, choose, revise, current} from '../web/story-model.mjs';
import * as model from '../web/story-model.mjs';

test('reading order reveals sources without merging fictional owners', () => {
  let state = createJourney();
  assert.deepEqual(current(state).page.refs, ['J2']);
  state = move(move(state, 1), 1);
  assert.equal(state.step, 2);
  assert.equal(choose(state, 'J').step, 2);
  state = choose(state, 'K');
  assert.equal(state.step, 0);
  assert.deepEqual(current(state).page.refs, ['K1']);
  assert.ok(current(move(move(state, 1), 1)).sources.every(s => s.id.startsWith('K')));
});

test('corrections stay with their person and reading step and can be removed', () => {
  let state = revise(createJourney(), 'A different explanation');
  assert.equal(current(state).correction, 'A different explanation');
  assert.equal(current(move(state, 1)).correction, '');
  assert.equal(current(choose(state, 'K')).correction, '');
  state = choose(choose(state, 'K'), 'J');
  assert.equal(current(state).correction, 'A different explanation');
  assert.equal(current(revise(state, '')).correction, '');
});

test('language changes preserve source identity and corrections are text', () => {
  const state = revise(createJourney(), '<img src=x onerror=alert(1)>');
  assert.deepEqual(current(state).page.refs, current({...state, language: 'en'}).page.refs);
  assert.equal(current(state).correction, '<img src=x onerror=alert(1)>');
  assert.throws(() => choose(state, 'unknown'));
  assert.equal(move(state, -1).step, 0);
  assert.equal(move(state, 99).step, 2);
});

test('the scene comparison includes each correction under its own source set', () => {
  let state = revise(createJourney(), 'My first-scene reading');
  state = move(move(state, 1), 1);
  assert.equal(current(state).readPages[0].correction, 'My first-scene reading');
  assert.equal(current(state).readPages[1].correction, '');
  assert.deepEqual(current(state).readPages[0].sources.map(s => s.id), ['J2']);
});

test('R compares requested answers and keeps a colleague quotation in its own scene', () => {
  let state = choose(createJourney(), 'R');
  assert.deepEqual(current(state).page.refs, ['R1']);
  state = move(state, 1);
  assert.deepEqual(current(state).page.refs, ['R1', 'R2']);
  state = revise(state, 'My reading of R');
  assert.equal(current(choose(state, 'J')).correction, '');
  state = move(state, 1);
  assert.deepEqual(current(state).page.refs, ['R3']);
  assert.ok(current(state).sources.every(source => source.id.startsWith('R')));
  assert.equal(current(state).readPages[1].correction, 'My reading of R');
});

test('Korean sources remain verbatim when an English translation is shown', () => {
  const source = current(choose(createJourney(), 'R')).sources[0];
  const english = model.sourceDisplay(source, 'en');
  assert.equal(english.originalLanguage, 'ko');
  assert.equal(english.original, '이 답변은 회의에서 읽을 거예요. 배경과 예시를 충분히 넣어 주세요.');
  assert.equal(english.translation, source.en);
  assert.equal(model.sourceDisplay(source, 'ko').translation, '');
  const oldSource = current(createJourney()).sources[0];
  assert.equal(model.sourceDisplay(oldSource, 'ko').original, oldSource.en);
  assert.equal(model.sourceDisplay(oldSource, 'ko').translation, oldSource.ko);
});
